-- 2026-11-20 每日收录：Voidcall、SineRider、Incremancer、进度骑士、太空公司，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('voidcall', 'Voidcall', 'Voidcall', 'voidcall void call jishi zhanlue rts phoboslab dominic szablewski', 'Dominic Szablewski (Phoboslab)', '', '', NULL, '', 0, 2019, 'action', '["策略","即时战略","3D"]', 270, 0.1, 'io', 'https://phoboslab.org/voidcall/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '在 13KB 里打一场迷你即时战略', '一款微型即时战略：点选单位、采集资源、在树林里把敌军清掉。', 'A tiny real-time strategy game: select units, gather resources, and clear the enemy in the woods.', '由 Dominic Szablewski（Phoboslab）制作，音乐由 Andreas Lösch 创作，是 2019 年 js13kGames 的作品，源码以 MIT 许可在 GitHub 发布。原页托管在 phoboslab.org/voidcall，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by Dominic Szablewski (Phoboslab) with music by Andreas Lösch for js13kGames 2019; the source is MIT-licensed on GitHub. Hosted at phoboslab.org/voidcall; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/voidcall.jpg', 1280, 800, 'center', '["assets/posters/voidcall.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -38, 1795140000000, 'A miniature real-time strategy packed into 13 KB.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('sinerider', 'SineRider', 'SineRider', 'sinerider sine rider zhengxian huaxue hanshu tuxiang hack club', 'Hack Club', '', '', NULL, '', 0, 2020, 'puzzle', '["益智","数学","平台"]', 320, 0.1, 'io', 'https://sinerider.com/', 0, 0, 0, 1, 0, 0, 1, 'mid', 'hosted', '用一条函数曲线，把雪橇滑下山', '一款关于爱与函数图像的游戏：写下一条曲线当作雪道，让角色顺着它滑下去，通过关卡。', 'A game about love and graphing: write a curve as a slope, and ride it through the level.', '由 Hack Club 的青少年制作，源码以 AGPL-3.0 许可在 GitHub 发布。原页托管在 sinerider.com，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by teenagers at Hack Club; the source is AGPL-3.0-licensed on GitHub. Hosted at sinerider.com; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/sinerider.jpg', 1280, 800, 'center', '["assets/posters/sinerider.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -37, 1795140000000, 'Write a function, and ride the curve downhill.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('incremancer', 'Incremancer', 'Incremancer', 'incremancer increment necromancer wailing jiangshi zombi jamesmgittins', 'jamesmgittins', '', '', NULL, '', 0, 2019, 'idle', '["放置","丧尸","策略"]', 120, 0.1, 'clicker', 'https://incremancer.gti.nz/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '点出一只亡灵，再养成一整支尸潮', '一款放置与即时战斗混合的游戏：消耗能量在地上召唤丧尸，攻打村落，再拿血液和大脑升级尸群。', 'A mix of idle and real-time combat: spend energy to spawn zombies, raid villages, and upgrade the horde with blood and brains.', '由 jamesmgittins 制作，并在 incremancer.gti.nz 公开发布，源码公开在 GitHub。原页托管在 incremancer.gti.nz，不是即玩的作品。在即玩里直接打开原作。开玩不用登录。', 'Made by jamesmgittins and published at incremancer.gti.nz, with source available on GitHub. Hosted at incremancer.gti.nz; it is not a Jiwan original. It opens here. No account needed.', 'assets/posters/incremancer.jpg', 1280, 800, 'center', '["assets/posters/incremancer.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -36, 1795140000000, 'Spawn one undead, then grow a whole horde.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('progress-knight', '进度骑士', 'Progress Knight', 'jindu qishi jinduqishi progress knight fangzhi juese bandyan ihtasham', 'Ihtasham (ihtasham42)', '', '', NULL, '', 0, 2020, 'idle', '["放置","角色扮演"]', 0, 0.08, 'clicker', 'https://ihtasham42.github.io/progress-knight/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '从乞讨开始，把一辈子慢慢点满', '一款放置角色扮演：打工、学技能、赚钱，过完一生后再转生，把下一辈子过得更远。', 'An idle role-playing game: work, train, earn, finish a life, then reincarnate and go farther the next time.', '由 Ihtasham（ihtasham42）制作，源码以 Unlicense 捐入公共领域。原页托管在 ihtasham42.github.io/progress-knight，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by Ihtasham (ihtasham42); the source is released into the public domain under the Unlicense. Hosted at ihtasham42.github.io/progress-knight; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/progress-knight.jpg', 1280, 800, 'center', '["assets/posters/progress-knight.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -35, 1795140000000, 'Start as a beggar, and slowly fill out a whole life.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('space-company', '太空公司', 'Space Company', 'taikong gongsi taikonggongsi space company wa kuang zao chuan sparticle999 alex scruton', 'Alex Scruton (Sparticle999)', '', '', NULL, '', 0, 2016, 'idle', '["放置","经营","太空"]', 200, 0.08, 'clicker', 'https://sparticle999.github.io/SpaceCompany/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '挖矿、造船，把公司送进太空', '一款放置经营：先点金属、宝石和木头，再买自动矿机，一步步造出能飞离地球的船。', 'An idle company sim: click metal, gems and wood, buy auto-miners, and gradually build a ship that can leave Earth.', '由 Alex Scruton（Sparticle999）制作，源码以 MIT 许可在 GitHub 发布。原页托管在 sparticle999.github.io/SpaceCompany，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by Alex Scruton (Sparticle999); the source is MIT-licensed on GitHub. Hosted at sparticle999.github.io/SpaceCompany; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/space-company.jpg', 1280, 800, 'center', '["assets/posters/space-company.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -34, 1795140000000, 'Mine, build a ship, and send the company into space.', '', '', 1);
